load=lambda p:json.loads((ROOT/p).read_text());sha=lambda p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest();idsBytes=lambda ids:('\n'.join(ids)+('\n' if ids else '')).encode()
d=load('Translations/bg/semantic-delta-cycle-002.json');c=load('Translations/bg/semantic-closure-cycle-002.json');rows=d['nextReviewRows'];findings=load('Translations/bg/independent-review-02/findings.json')['findings'];issues={f['stableId']:f for f in findings};pins=load('Translations/bg/independent-review-02/input-verification.json');assert len(rows)==2110
