mandatory=c['components']['mandatoryRegressions']['ids'];fresh=[x for x in mandatory if x in set(readIds)];reuse=pins['priorApplicableIds'];assert set(fresh)|set(reuse)==set(mandatory);assert not set(fresh)&set(reuse);(OUT/'mandatory-fresh-read.ids').write_bytes(idsBytes(fresh));(OUT/'mandatory-prior-applicable.ids').write_bytes(idsBytes(reuse))
