 ledger.append({'deltaIndex':i,'stableId':r['stableId'],'sourceSha256':hashlib.sha256(r['source'].encode()).hexdigest(),'targetSha256':hashlib.sha256(r['target'].encode()).hexdigest(),'fullPairRead':True,'verdict':'objective finding' if r['stableId'] in issues else 'no additional objective correction proposed after independent full-pair read','findingId':issues.get(r['stableId'],{}).get('findingId'),'sceneNodes':r['sceneNodes'],'sourceIndex':r['sourceIndex']})
