review={'schemaVersion':1,'reviewer':'/root/bg_independent_review_02','independence':'Separate no-history assigned reviewer; no delegation; no authored inputs or shared evidence modified','model':'Codex GPT-6 family; exact backend identifier not exposed','reasoningLevel':'not exposed','game':"No, I'm not a Human",'gameVersion':'1.3.19','sourceLocale':'ru','targetLocale':'bg','scope':'exact cycle-002 text delta; translated images and textures excluded','status':'independent review complete with findings; CLEAN rejected','deltaSha256':sha('Translations/bg/semantic-delta-cycle-002.json'),'closureSha256':sha('Translations/bg/semantic-closure-cycle-002.json'),'correctionPlanSha256':sha('Translations/bg/correction-batch-002.json'),'coverage':{'completeDeltaPairsRead':2110,'indicesInclusive':[0,2109],'rereadTruncatedIntervalsInclusive':[[88,93],[740,756]],'readIdsPath':'Translations/bg/independent-review-02/read.ids','readIdsSha256':hashlib.sha256(readRaw).hexdigest(),'mandatoryIdsChecked':908,'freshMandatoryPairsRead':401,'exactPriorApplicableMandatoryPairs':507,'mandatoryCompleteIdsSha256':c['components']['mandatoryRegressions']['sha256'],'all735CanonicalVoicePairsFreshlyRead':True,'selectorSupplementaryPairsOutsideDeltaRead':4,'allCorpusRereadClaim':False},'mandatoryRegressions':{k:{'count':v['count'],'idsSha256':v['idsSha256'],'freshDeltaReads':len(set(v['ids'])&set(readIds)),'priorExactApplicable':len(set(v['ids'])&set(reuse)),'result':'checked under exact current hashes'} for k,v in c['mandatoryRegressionGroups'].items()},'findings':{'fullUnitProposalCount':len(findings),'selectorFindingCount':1,'applied':False,'findingsSha256':sha('Translations/bg/independent-review-02/findings.json'),'selectorFindingSha256':sha('Translations/bg/independent-review-02/selector-findings.json')},'preflight':{'normalClosureVerify':'passed at start and required end','normalDeltaVerify':'passed at start and required end','all411AuthoredAnd411ValidationReceiptPins':'passed unchanged at start and sealing','sourceGlossaryConsumerAndRecipePins':'passed unchanged','completeCurrentTargetMap':16538,'changedFullUnitsExactlyMatchAcceptedPlan':147,'beforeTargetSourceIndependentStoredPriorRows':36,'beforeOther111':'Plan currentFullTarget and baseline file hashes retained; no absent historical authored bytes reconstructed or claimed','proposalPrefixAndSlotMarkupExactComparison':'passed for all 43 proposals; does not replace author full preservation and runtime preflight'},'context':{'compiledNodeCount':3255,'rawProgramReparse':'exact JSON-normalized equality with pinned compiled nodes','compiledProgramSha256':'33de1e80e55e4eb8ec2093078028aa83fc45ac8b77acc05c5a4f9477ebe92827','dialogueDeltaRowsWithCompiledUses':pins['usageCount'],'dialogueRowsWithoutCompiledUses':len(pins['noCompiledUseIds']),'noCompiledUseIds':pins['noCompiledUseIds'],'method':'Every mapped pair was inspected with actual compiled node/instruction and option indication, rather than assuming table neighbors were sequential. Full control flow and source dialogue were separately read for ambiguity-bearing gun, nun, colour, kinship, sign-reference and dynamic-occupant scenes. Consumer parse/substitution and provider evidence remain pinned source-context aids, not physical runtime evidence.','specialChecks':['Nun_Ears service-prefix and female release choice fixed','Rocker_Photo→Rocker_Photo_Gun cap joke retains cap referent across camera→gun transition','Unstable_Photo_Gun heart referent and beating action retained','Bald mother/grandmother family identified from glossary and later exact scene','Static Unlock cat/CRITICAL REFLEX/Wishlist/beer referent fixes read in full'],'physicalRuntime':'not run; owner excluded launch','fontsLayoutVisual':'not run; no rendered text or parity claim'},'acceptance':{'completeAssignedPairRead':True,'cleanIndependentDeltaAudit':False,'selectorComplete':False,'mandatoryRegressionEditorialDefectWithinCatalog':False,'editorialAcceptance':False,'integrationBuildRuntimeVisualRelease':'pending root/owner workflow'},'telemetry':{'inputTokens':None,'cachedInputTokens':None,'outputTokens':None,'reasoningTokens':None,'totalTokens':None,'note':'No per-request token telemetry or agent/session usage counter is exposed to this reviewer. Unknown is not zero. Root may independently obtain a session-keyed measurement; this report does not estimate tokens from corpus size. Reporting tail is unmeasured.'},'nextAction':'Root returns all 43 objective full-unit proposals and the bounded selector finding to the author in one batch. Author adjudicates, repairs normal selector recipe, preflights complete replacements, applies accepted corrections together, and generates an immutable exact next delta. Preserve full first-pass evidence; no automatic full 16538-unit restart, runtime launch or Git mutation.'}
(OUT/'review.json').write_text(json.dumps(review,ensure_ascii=False,indent=2)+'\n');print({'pairs':2110,'freshRegressions':len(fresh),'reusedRegressions':len(reuse),'fullUnitFindings':len(findings),'missingSelectorIds':len(missed),'sourceTargetsUnchanged':True})
